response.output:
{
  "world_id": "wld_glass_tide",
  "name": "The Littoral of Bellwater",
  "description": "Bellwater is a solarpunk city built around a broad, shallow lagoon whose rising and falling waters turn communal mills, lift cargo, and carry fresh water through the terraces. Its glassworks catch sunlight by day and shape it into colored panes that help grow food in the city’s winter gardens. Now the lagoon gates are silting shut weeks ahead of schedule. Mara, a junior tide-warden, must persuade powerful guilds to pause the glassblowing season before the city loses the tide that sustains it. Hope here is practical: neighbors share tools, engineers publish their findings, and even a costly halt may open the way to a fairer design. A strange local measure complicates the crisis: old gatekeepers recorded each tide not by height, but by the number of bell notes it carried through submerged stone chambers.",
  "locations": [
    {
      "id": "loc_siltglass_lagoon",
      "name": "Siltglass Lagoon",
      "description": "A tidal basin edged by gardens and low seawalls. Fine mineral silt clouds its channels, and the water’s changing color lets experienced wardens spot a blocked current before instruments do."
    },
    {
      "id": "loc_sunward_furnaces",
      "name": "Sunward Furnaces",
      "description": "A guild of glassblowers works with mirrored solar kilns on a high terrace. Its luminous panes are prized across Bellwater, but a full season’s production draws workers and materials away from urgent gate repairs."
    },
    {
      "id": "loc_bellchamber_gates",
      "name": "The Bellchamber Gates",
      "description": "A row of tidal sluices whose stone throats ring at different pitches as water passes. Their original tuning marks record a pattern that the current gate schedule no longer matches."
    },
    {
      "id": "loc_reedline_common",
      "name": "Reedline Common",
      "description": "A floating market and meeting ground of reed walkways, repair sheds, and shared cisterns. Fishers, growers, and apprentices compare observations here, beyond the guilds’ formal ledgers."
    }
  ],
  "factions": [
    {
      "id": "fac_tidewardens",
      "name": "The Tidewardens",
      "description": "Keepers of the gates and public water records. They trust patient measurements, but their junior members have little authority when senior guilds dispute a warning.",
      "location_ids": [
        "loc_bellchamber_gates",
        "loc_siltglass_lagoon"
      ]
    },
    {
      "id": "fac_sunward_guild",
      "name": "The Sunward Glass Guild",
      "description": "Artisans and traders who operate the solar kilns. Many care deeply for the city, yet a canceled season could cost apprentices their wages and the guild its contracts.",
      "location_ids": [
        "loc_sunward_furnaces"
      ]
    },
    {
      "id": "fac_reedline_cooperative",
      "name": "Reedline Cooperative",
      "description": "Fishers, gardeners, haulers, and cistern stewards who maintain shared services. They want the tide protected, and insist that any shutdown distribute its burdens fairly.",
      "location_ids": [
        "loc_reedline_common",
        "loc_siltglass_lagoon"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tidal_power",
      "statement": "The city’s large mills and lifting platforms work only when lagoon tides pass through the gate channels.",
      "category": "physics"
    },
    {
      "id": "rul_silt_cycles",
      "statement": "Seasonal currents deposit silt in the lagoon; opening and closing gates in the proper sequence clears some channels, while a mistimed sequence compacts sediment against the sluices.",
      "category": "physics"
    },
    {
      "id": "rul_solar_craft",
      "statement": "Glass is melted in concentrated sunlight and shaped with hand tools; no combustion engines or fossil fuels are used anywhere in Bellwater.",
      "category": "technology"
    },
    {
      "id": "rul_shared_water",
      "statement": "Cistern water and gate access are held in trust for the city, and guilds may not privately divert them without public review.",
      "category": "social"
    },
    {
      "id": "rul_bell_measure",
      "statement": "The submerged gate chambers change the lagoon’s bell pattern when currents shift, offering an independent warning that water-height gauges can miss.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_first_tuning",
      "name": "The First Tuning",
      "description": "When Bellwater’s first sluices were built, stonecutters shaped each chamber to ring at a distinct pitch. Their bell ledger became a civic record of safe gate sequences.",
      "era": "Founding era",
      "location_ids": [
        "loc_bellchamber_gates"
      ]
    },
    {
      "id": "evt_mirror_gardens",
      "name": "The Mirror Garden Accord",
      "description": "Glassmakers and growers agreed to share sunlight infrastructure: kiln mirrors would be angled seasonally to serve both craft and food production.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_sunward_furnaces",
        "loc_reedline_common"
      ]
    },
    {
      "id": "evt_quiet_sediment",
      "name": "The Quiet Sediment Years",
      "description": "A stretch of unusually gentle tides left the gates with less routine clearing. The city celebrated steady output, while maintenance notes slowly disappeared from the public schedule.",
      "era": "Recent decades",
      "location_ids": [
        "loc_siltglass_lagoon",
        "loc_bellchamber_gates"
      ]
    },
    {
      "id": "evt_early_warning",
      "name": "The Early Warning",
      "description": "Mara compares the bell ledger with fresh measurements and finds that silting is weeks ahead of the expected cycle. The discrepancy points to a gate sequence that has been repeated for years despite changed currents.",
      "era": "Present season",
      "location_ids": [
        "loc_bellchamber_gates",
        "loc_reedline_common"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_halt_or_harvest",
      "name": "Halt or Harvest",
      "description": "The Tidewardens urge an immediate pause in glassblowing so crews can clear and retune the gates. The Glass Guild fears ruinous lost contracts, while the Cooperative warns that workers must not bear the cost alone.",
      "faction_ids": [
        "fac_tidewardens",
        "fac_sunward_guild",
        "fac_reedline_cooperative"
      ]
    },
    {
      "id": "cnf_ledger_or_bells",
      "name": "Ledger or Bells",
      "description": "Official schedules still call the gates safe, but their bell pattern contradicts the written record. Some senior keepers suspect flawed measurements; others fear admitting that years of neglected maintenance made the warning easy to ignore.",
      "faction_ids": [
        "fac_tidewardens",
        "fac_reedline_cooperative"
      ]
    }
  ]
}

