{
  "world_id": "wld_mistwake_isles",
  "name": "The Mistwake Isles",
  "description": "A chain of steep, rain-bright islands lies beneath a roaming mantle of sea mist. Here, sword schools guard old covenants as carefully as they guard their passes, and a teacher's tally-stick can carry more weight than a lord's seal. When her master dies, a disowned student inherits his split tally and the duty to bear it to three rival sects, calling them to a peace moot before their feud destroys the last crane rookeries. The islands' strange currents, ceremonial combat, and fragile wetlands make every journey a test of restraint as much as skill. The mist keeps old words close to the water, and the cranes return each year to the same reeds—if the clans leave them standing.",
  "locations": [
    {
      "id": "loc_saltglass_harbor",
      "name": "Saltglass Harbor",
      "description": "A sheltered port of green-glazed roofs and tide stairs, where ferrymen read the mist as others read a chart. The late master's school once received students here; its gate now bears the mark of his student's disowning."
    },
    {
      "id": "loc_reedcrown_marsh",
      "name": "Reedcrown Marsh",
      "description": "A broad wetland of mirror pools and floating reed paths, refuge to the islands' final great crane rookery. Clan wardens allow no drawn blade among the nesting beds, even when their own banners face one another across the water."
    },
    {
      "id": "loc_bellwind_pass",
      "name": "Bellwind Pass",
      "description": "A knife-thin mountain crossing lined with bronze bells. Their tones reveal shifts in the cloud-hidden currents, and a challenger who rings the pass's middle bell announces a formal duel before witnesses."
    },
    {
      "id": "loc_ashen_moot_isle",
      "name": "Ashen Moot Isle",
      "description": "A low, black-stone island where an old council hall stands open to the sea. Its circular floor is divided by three channels, so rival delegations must share one roof without claiming the center."
    }
  ],
  "factions": [
    {
      "id": "fac_white_reed_school",
      "name": "White Reed School",
      "description": "A sword sect devoted to yielding without surrender. It disowned the master's student after she refused to endorse a retaliatory strike, yet its elders still recognize the tally-stick's authority.",
      "location_ids": ["loc_saltglass_harbor", "loc_reedcrown_marsh"]
    },
    {
      "id": "fac_bronze_current_clan",
      "name": "Bronze Current Clan",
      "description": "Keepers of the eastern channels, whose boat-swords and bell rites make them formidable guardians of the crossings. They demand repayment for an old injury before they will attend any moot.",
      "location_ids": ["loc_bellwind_pass", "loc_saltglass_harbor"]
    },
    {
      "id": "fac_black_cairn_sect",
      "name": "Black Cairn Sect",
      "description": "A highland sword fellowship that believes a promise has no force until tested in public. Its members will hear the tally-stick, but only if the other clans arrive under their own names and colors.",
      "location_ids": ["loc_bellwind_pass", "loc_ashen_moot_isle"]
    },
    {
      "id": "fac_rookery_wardens",
      "name": "Rookery Wardens",
      "description": "Marsh families who tend the nesting islands and keep records in reed knots. They are not a sword sect, but hold the only seasonal passage map that reaches the moot isle safely.",
      "location_ids": ["loc_reedcrown_marsh", "loc_ashen_moot_isle"]
    }
  ],
  "rules": [
    {
      "id": "rul_tally_witness",
      "statement": "A master's tally-stick may call a peace moot only when its bearer presents it before witnesses from each named sect.",
      "category": "social"
    },
    {
      "id": "rul_formal_challenge",
      "statement": "Duels are settled by formal challenge in the presence of witnesses; ambush is forbidden by island law and brings dishonor upon the challenger's whole school.",
      "category": "social"
    },
    {
      "id": "rul_bellwind_currents",
      "statement": "The mountain bells answer shifts in the sea mist's hidden currents, making the pass's safe route change with the tide.",
      "category": "metaphysics"
    },
    {
      "id": "rul_rookery_truce",
      "statement": "No clan may carry a drawn weapon into a nesting bed while cranes are raising young; wardens may bar any offender from the marsh paths.",
      "category": "social"
    },
    {
      "id": "rul_swordcraft",
      "statement": "Island sword schools teach steel, staff, and empty-hand forms; none keeps a weapon that strikes from afar without a wielder's direct reach.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_three_channel_covenant",
      "name": "The Three-Channel Covenant",
      "description": "After a season of bloodshed, the island schools agreed to hold disputes at Ashen Moot Isle, whose divided hall gave no clan the center seat. The covenant established public challenges and a shared duty to keep the marsh paths open.",
      "era": "Founding era",
      "location_ids": ["loc_ashen_moot_isle", "loc_bellwind_pass"]
    },
    {
      "id": "evt_silent_spring",
      "name": "The Silent Spring",
      "description": "A feud drove the clans to burn reed beds during nesting season. The cranes abandoned two islands, and the remaining families began the rookery truce, entrusting the marsh records to wardens outside the sword schools.",
      "era": "A generation ago",
      "location_ids": ["loc_reedcrown_marsh"]
    },
    {
      "id": "evt_split_tally",
      "name": "The Split Tally",
      "description": "The late master broke his tally-stick in two after his pupils refused a retaliatory strike. He gave one half to his student and sent the other to the harbor school, saying that a divided record could still call divided people to account.",
      "era": "Recent years",
      "location_ids": ["loc_saltglass_harbor"]
    },
    {
      "id": "evt_master_last_walk",
      "name": "The Master's Last Walk",
      "description": "Before his death, the master crossed Bellwind Pass alone and left a sealed invitation at the moot hall. The clans dispute what he promised them; his student's journey is the first chance to place the full tally before all three sects.",
      "era": "Present season",
      "location_ids": ["loc_bellwind_pass", "loc_ashen_moot_isle"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_rookery_last_nesting",
      "name": "The Last Nesting",
      "description": "The clans' feud is spreading toward Reedcrown Marsh just as the cranes return. The wardens will close the safe passage if fighting reaches the nesting beds, potentially stranding the student's mission and leaving the rookery defenseless.",
      "faction_ids": ["fac_bronze_current_clan", "fac_black_cairn_sect", "fac_rookery_wardens"]
    },
    {
      "id": "cnf_tally_bearers_claim",
      "name": "Who May Bear the Tally",
      "description": "White Reed elders say a disowned student cannot speak for her master; the other sects suspect the school wants to suppress his final terms. The bearer must win recognition without turning the journey into the very challenge she was cast out for refusing.",
      "faction_ids": ["fac_white_reed_school", "fac_bronze_current_clan", "fac_black_cairn_sect"]
    },
    {
      "id": "cnf_unpaid_wound",
      "name": "The Unpaid Wound",
      "description": "Bronze Current demands satisfaction for an injury it attributes to Black Cairn, while Black Cairn insists the accusation was never made through a formal challenge. Both can attend the moot only if neither is forced to arrive under the other's terms.",
      "faction_ids": ["fac_bronze_current_clan", "fac_black_cairn_sect"]
    }
  ]
}

