response.output:
{
  "world_id": "wld_sunside_yard",
  "name": "Sunside Yard",
  "description": "Inside Mercury's orbit, Sunside is a working shipyard where solar-sail craft are built, patched, and sent on patient, fuel-conscious routes through the inner system. Crews live by orbital windows, heat budgets, and the slow arithmetic of light: a missed transfer can cost months, while a badly timed maneuver can strand a vessel in the wrong orbit. Salvage rigger Nera Venn finds a hull listed as scrapped still drawing power through a yard service line. The evidence is real but easy to misread, and the charter auditors are due before she can trace the feed. The yard's unusual accounting system records each berth's power use as a moving pattern of shadow across a calibrated sun-screen, making the logs both a practical engineering tool and a closely guarded instrument of ownership. In this gritty workplace, proving what happened may be as dangerous as keeping the shipyard solvent.",
  "locations": [
    {
      "id": "loc_sunside_cradle",
      "name": "Sunside Cradle",
      "description": "The yard's main assembly berth, a trusswork frame aimed to keep its work bays in controlled light. Sails are unfolded here under strict limits on glare, thermal stress, and the tiny forces that can shift a docked hull."
    },
    {
      "id": "loc_shadow_ledger",
      "name": "Shadow Ledger Gallery",
      "description": "A narrow observation gallery behind the yard's sun-screen. Technicians compare the screen's timed shadow marks with power meters to assign energy use to individual berths; a carefully placed obstruction can disguise a draw without altering the written account."
    },
    {
      "id": "loc_keel_market",
      "name": "Keel Market",
      "description": "A pressurized salvage exchange built into an old cargo spine. Tools, certified parts, and undocumented fittings change hands under watchful cameras, while workers trade practical knowledge the official maintenance records omit."
    },
    {
      "id": "loc_scrap_drift",
      "name": "Scrap Drift",
      "description": "A controlled orbit of decommissioned frames and tagged hulls awaiting dismantling or transfer. Each object follows a known track; crews use scheduled tug burns and visual checks to prevent the slow orbital clutter from becoming a collision hazard."
    }
  ],
  "factions": [
    {
      "id": "fac_charter_office",
      "name": "Inner Orbit Charter Office",
      "description": "The authority that licenses yard berths, audits power allotments, and certifies that scrapped property has been rendered inactive. Its auditors are under pressure to show that the charter system can police itself.",
      "location_ids": [
        "loc_shadow_ledger",
        "loc_sunside_cradle"
      ]
    },
    {
      "id": "fac_sunside_crew",
      "name": "Sunside Rigging Cooperative",
      "description": "Riggers and repair hands who keep the yard operating through shared skills and mutual aid. They want the live hull investigated, but fear that a public scandal will cost the crew their contracts and housing.",
      "location_ids": [
        "loc_sunside_cradle",
        "loc_keel_market"
      ]
    },
    {
      "id": "fac_reclaim_union",
      "name": "Reclaim Union",
      "description": "Salvage crews who claim abandoned and scrapped material under a strict chain of custody. A hull still taking power threatens their claims, though some members suspect the yard has been quietly diverting their allotments.",
      "location_ids": [
        "loc_scrap_drift",
        "loc_keel_market"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_orbital_motion",
      "statement": "Every vessel and loose object follows ordinary orbital mechanics; changing a trajectory requires a measurable impulse and enough time to arrange it.",
      "category": "physics"
    },
    {
      "id": "rul_light_delay",
      "statement": "Communication travels no faster than light, so messages between separated craft arrive with delays that vary with their positions.",
      "category": "physics"
    },
    {
      "id": "rul_sail_propulsion",
      "statement": "A solar sail gains small, continuous thrust from sunlight, and its acceleration depends on sail area, reflectivity, orientation, and distance from the Sun.",
      "category": "technology"
    },
    {
      "id": "rul_thermal_limits",
      "statement": "Near Mercury, equipment must shed or redirect substantial heat; unplanned exposure can damage seals, sensors, and power systems.",
      "category": "physics"
    },
    {
      "id": "rul_shadow_accounting",
      "statement": "The yard's charter assigns berth power by matching calibrated sun-screen shadows to independent meter records; changing either record leaves a detectable mismatch.",
      "category": "social"
    },
    {
      "id": "rul_scrap_custody",
      "statement": "A hull marked for scrapping remains under its recorded owner's custody until its power links are isolated and its disposition is witnessed.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_cradle",
      "name": "The First Cradle Opens",
      "description": "The yard began as a small repair frame serving sail craft on inner-system routes. Its founders built the sun-screen gallery to make power allotments verifiable without trusting a single meter.",
      "era": "Founding years",
      "location_ids": [
        "loc_sunside_cradle",
        "loc_shadow_ledger"
      ]
    },
    {
      "id": "evt_shadow_compact",
      "name": "The Shadow Compact",
      "description": "After a disputed energy bill threatened to close the yard, crews and charter officials agreed to pair shadow observations with meter readings. The compromise stabilized the charter but gave the office leverage over every berth's operating record.",
      "era": "Charter settlement",
      "location_ids": [
        "loc_shadow_ledger",
        "loc_sunside_cradle"
      ]
    },
    {
      "id": "evt_salvage_partition",
      "name": "The Salvage Partition",
      "description": "A shortage of reliable materials led to a formal division between repair stock and reclaim property. The union gained custody rights over tagged hulls, while the charter office kept authority to certify final disposal.",
      "era": "Expansion period",
      "location_ids": [
        "loc_scrap_drift",
        "loc_keel_market"
      ]
    },
    {
      "id": "evt_live_scrap_entry",
      "name": "The Live Scrap Entry",
      "description": "A hull was entered in the ledger as dismantled, yet its berth continued to register a faint power draw. The discrepancy passed routine review because the shadow record appeared consistent; the next charter audit may expose the hidden link.",
      "era": "Present",
      "location_ids": [
        "loc_scrap_drift",
        "loc_shadow_ledger"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_power_trace",
      "name": "The Unclaimed Draw",
      "description": "The rigging cooperative wants time to trace the live hull's supply line before the auditors arrive. The charter office wants the books settled on schedule, while the reclaim union fears that either explanation could erase its claim to the hull or reveal that its salvage allotment has been siphoned.",
      "faction_ids": [
        "fac_charter_office",
        "fac_sunside_crew",
        "fac_reclaim_union"
      ]
    },
    {
      "id": "cnf_audit_deadline",
      "name": "The Audit Window",
      "description": "The auditors' arrival is fixed by their transfer schedule, not by the yard's needs. Crew members must choose whether to preserve the evidence, protect coworkers from blame, or secure the contracts that keep the yard operating.",
      "faction_ids": [
        "fac_charter_office",
        "fac_sunside_crew"
      ]
    }
  ]
}

