response.output:
{
  "world_id": "wld_rain_remembers",
  "name": "The Rainward Vale",
  "description": "In the years after the fall of the old world, four valley towns depend on a seedway of footpaths, mule tracks, and hand-built bridges. A seed-keeper's caravan must carry grain between them before the last frost, when a missed planting could leave whole hamlets hungry until spring. The route was once shared, but a feud over a vanished harvest split it into rival branches. Now rain brings buried seeds to the surface—and, in one unusual hollow, the colors of those seedlings reliably match the rainwater that fed them, letting careful growers trace where a season's water has traveled. The towns disagree over what that sign proves, but the caravan may need it to mend the feud. Wistful and hard-won hope lives alongside practical work: mending tools, saving grain, and deciding what must be shared.",
  "locations": [
    {
      "id": "loc_millford",
      "name": "Millford Weir",
      "description": "A riverside town built around a cracked stone weir and a hand-turned grain mill. Its storehouse holds the largest reserve in the valley, guarded by a council that fears another failed harvest."
    },
    {
      "id": "loc_ashcombe",
      "name": "Ashcombe Terrace",
      "description": "A hillside settlement of stepped gardens and soot-dark sheds, where growers keep seed in clay jars above the damp. Its steep old path is the shorter seedway branch, but a feud has left its bridge unrepaired."
    },
    {
      "id": "loc_siltmere",
      "name": "Siltmere Hollow",
      "description": "A low town among reed beds and flood-marked cottages. After heavy rain, pale seedlings appear in the mud in bands of color that follow the water's path, a living record whose meaning is fiercely disputed."
    },
    {
      "id": "loc_frostgate",
      "name": "Frostgate Common",
      "description": "A windswept meeting ground at the valley's northern pass, ringed by abandoned stone walls. Each autumn, the towns once exchanged grain and settled route disputes here before the first frost sealed the high trail."
    }
  ],
  "factions": [
    {
      "id": "fac_seedwardens",
      "name": "The Seedwardens",
      "description": "A small traveling fellowship that tests seed, mends hand-tools, and keeps records of what each valley can spare. Their keeper carries an old route ledger whose missing pages may explain how the feud began.",
      "location_ids": [
        "loc_millford",
        "loc_ashcombe",
        "loc_siltmere",
        "loc_frostgate"
      ]
    },
    {
      "id": "fac_weir_council",
      "name": "Millford Weir Council",
      "description": "Millers and storehouse stewards who control the valley's largest grain reserve. They will release stock only if the other towns accept a common measure and guarantee a share of the next harvest.",
      "location_ids": [
        "loc_millford",
        "loc_frostgate"
      ]
    },
    {
      "id": "fac_terrace_compact",
      "name": "The Terrace Compact",
      "description": "Ashcombe growers and Siltmere reed-cutters bound by mutual aid, but divided over whether the old short route should be reopened. Some trust the colored seedlings as evidence; others see them as a dangerous excuse to claim water and land.",
      "location_ids": [
        "loc_ashcombe",
        "loc_siltmere"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_seasons",
      "statement": "The valley follows ordinary seasons, and the first hard frost ends planting for the year.",
      "category": "physics"
    },
    {
      "id": "rul_watermarks",
      "statement": "In Siltmere Hollow, seedlings sprouting after rain take on faint colors that correspond to the rainwater's path through the valley; the pattern records flow, not ownership or intent.",
      "category": "metaphysics"
    },
    {
      "id": "rul_handwork",
      "statement": "No powered machinery remains in working use; travel, milling, building, and harvest depend on people, animals, water, and salvaged hand-tools.",
      "category": "technology"
    },
    {
      "id": "rul_seedkeeping",
      "statement": "Seed saved for planting must be dried and sealed before the damp season, or it loses much of its ability to sprout.",
      "category": "other"
    },
    {
      "id": "rul_common_measure",
      "statement": "Grain trades are recognized by all four towns only when both parties witness the measure and mark the amount in a shared ledger.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_split_harvest",
      "name": "The Missing Measure",
      "description": "Years ago, a grain shipment meant for Ashcombe arrived at Millford short. Millford blamed a flood; Ashcombe accused the weir stewards of keeping the missing sacks. With no trusted ledger to settle the matter, the towns closed the short branch of the seedway.",
      "era": "Years of the Split Route",
      "location_ids": [
        "loc_millford",
        "loc_ashcombe",
        "loc_frostgate"
      ]
    },
    {
      "id": "evt_silt_records",
      "name": "The First Colored Shoots",
      "description": "After a season of unusual floods, Siltmere children noticed that bands of differently colored seedlings followed the channels left by the rain. Their elders began recording the patterns, though the notes were never accepted as proof in the grain dispute.",
      "era": "Years of the Split Route",
      "location_ids": [
        "loc_siltmere"
      ]
    },
    {
      "id": "evt_last_gathering",
      "name": "The Abandoned Common",
      "description": "The autumn exchange at Frostgate ended when neither rival group would cross the other's path. The meeting walls remain, and old marks cut into their stones still show where each town once stacked its grain.",
      "era": "The Last Shared Autumn",
      "location_ids": [
        "loc_frostgate"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_grain_route",
      "name": "The Split Seedway",
      "description": "Millford's reserve could carry the towns through winter, but the council refuses to send grain along a route it cannot audit. Ashcombe and Siltmere need the shipment and reject terms that leave them dependent on Millford's ledger. The caravan must broker a measure both sides will witness before frost closes the pass.",
      "faction_ids": [
        "fac_weir_council",
        "fac_terrace_compact",
        "fac_seedwardens"
      ]
    },
    {
      "id": "cnf_meaning_of_rain",
      "name": "A Pattern Is Not a Verdict",
      "description": "The Seedwardens hope Siltmere's seedling bands can reveal how water moved during the disputed harvest. The Terrace Compact is divided over whether to trust those records, while the Weir Council fears that a pattern may be used to reopen old accusations without proving who took the grain.",
      "faction_ids": [
        "fac_seedwardens",
        "fac_weir_council",
        "fac_terrace_compact"
      ]
    }
  ]
}

