{
  "world_id": "wld_the_brass_quiet",
  "name": "The Brass Quiet",
  "description": "Beyond the last breath lies a country of counting-houses, slate canals, and patient bells, where every mortal life becomes an account before its soul is weighed. The dead do not return to life; only their accounts move. In these courts, a junior scribe discovers a soul entered in the wrong ledger column and must carry the correction upward through offices that treat urgency as a clerical defect. The Brass Quiet is a mythic realm with solemn laws and dry humor: its oldest judges fear an unbalanced total more than a storm, and even grief must wait for the proper docket.",
  "locations": [
    {
      "id": "loc_silt_gate",
      "name": "Silt Gate",
      "description": "A low arch at the edge of the dead country, where new arrivals surrender their names to clerks with ink-stained cuffs. The canal beyond carries account-scrolls, never souls."
    },
    {
      "id": "loc_lower_counting_house",
      "name": "Lower Counting-House",
      "description": "A cavernous office of echoing desks where junior scribes reconcile the freshly arrived with the old registers. Its lamps burn blue whenever a sum is disputed."
    },
    {
      "id": "loc_palace_of_columns",
      "name": "Palace of Columns",
      "description": "A many-storied archive whose stone pillars are carved with the names of ledger categories. Clerks climb ladders to amend entries, while the pillars quietly remember every earlier version."
    },
    {
      "id": "loc_copper_ford",
      "name": "Copper Ford",
      "description": "A shallow crossing where the account-books pass from record-keepers to assessors. The water runs over copper plates, and each ripple sounds like a number being reconsidered."
    },
    {
      "id": "loc_scale_chamber",
      "name": "Chamber of the Last Scale",
      "description": "A circular hall where an account is weighed against the life it describes. The balance has no pans: one side holds the written record, the other the silence left by its omissions."
    }
  ],
  "factions": [
    {
      "id": "fac_blue_quills",
      "name": "The Blue Quills",
      "description": "Junior record-keepers who believe a careful correction is a form of mercy. Their members carry portable inkstones and know which supervisors can be persuaded with evidence rather than ceremony.",
      "location_ids": [
        "loc_lower_counting_house",
        "loc_palace_of_columns"
      ]
    },
    {
      "id": "fac_final_assessors",
      "name": "The Final Assessors",
      "description": "Guardians of the weighing procedure, committed to closing each account in its appointed order. They fear that exceptions will make the whole measure unreliable, though some quietly suspect the columns have been wrong for generations.",
      "location_ids": [
        "loc_copper_ford",
        "loc_scale_chamber"
      ]
    },
    {
      "id": "fac_margin_keep",
      "name": "Keepers of the Margin",
      "description": "A discreet circle of archivists who preserve crossed-out entries in the narrow spaces beside official text. They claim the margins contain the only honest history the ledgers have.",
      "location_ids": [
        "loc_silt_gate",
        "loc_palace_of_columns"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_accounts_travel",
      "statement": "Only accounts move between offices; the dead remain in the realm and never return to mortal life.",
      "category": "metaphysics"
    },
    {
      "id": "rul_names_anchor",
      "statement": "A soul cannot be weighed until its recorded name is matched to a witnessed life.",
      "category": "metaphysics"
    },
    {
      "id": "rul_margin_memory",
      "statement": "An erased entry remains legible in the margins to anyone who has copied it by hand.",
      "category": "other"
    },
    {
      "id": "rul_seal_authority",
      "statement": "A correction is binding only when sealed by a clerk from a higher counting-house than the clerk who made the original entry.",
      "category": "social"
    },
    {
      "id": "rul_ledger_balance",
      "statement": "Every soul must be entered in the ledger before its account reaches the final scale.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_columns",
      "name": "The First Columns",
      "description": "The earliest judges divided the dead into categories to make the endless arrival of accounts manageable. They carved those categories into the Palace of Columns, believing stone would be more impartial than memory.",
      "era": "Founding Reckoning",
      "location_ids": [
        "loc_palace_of_columns"
      ]
    },
    {
      "id": "evt_margin_compact",
      "name": "The Margin Compact",
      "description": "After a generation of clerks found that official corrections kept vanishing, archivists agreed to preserve every disputed entry in the margins. The practice was called untidy and never formally prohibited.",
      "era": "Era of Ink Disputes",
      "location_ids": [
        "loc_lower_counting_house",
        "loc_palace_of_columns"
      ]
    },
    {
      "id": "evt_copper_measure",
      "name": "The Copper Measure",
      "description": "Assessors laid copper plates across the ford to mark the handover from record to judgment. Since then, every disputed account has made the crossing sound like rain on a clerk's roof.",
      "era": "Present Reckoning",
      "location_ids": [
        "loc_copper_ford",
        "loc_scale_chamber"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_wrong_column",
      "name": "The Misfiled Life",
      "description": "A newly arrived soul is listed in a column that would distort the final weighing. The Blue Quills seek a correction before the account reaches the scale, while the Final Assessors insist that changing the entry without proper seals could undermine every judgment.",
      "faction_ids": [
        "fac_blue_quills",
        "fac_final_assessors"
      ]
    },
    {
      "id": "cnf_margin_evidence",
      "name": "What the Margins Remember",
      "description": "The Keepers of the Margin hold old copies suggesting that the disputed column has been wrong for years. Revealing them could repair many accounts, but would also expose the assessors who certified the earlier totals.",
      "faction_ids": [
        "fac_margin_keep",
        "fac_final_assessors"
      ]
    }
  ]
}

