response.output:
{
  "world_id": "wld_ninth_bell_estuary",
  "name": "The Silted Cantons",
  "description": "In the Silted Cantons, an estuary city of drowned lanes and leaning parish towers, fog arrives with the tide and lingers long enough to acquire a reputation. Gas mantles and oil lamps give the streets their wavering light. The city’s storm-bells warn of surges, hidden shoals, and the rare fog that turns familiar water into a maze. Their patterns are guarded lore, cast into each bell’s shape by founders who insist that no two warnings should sound alike. When an apprentice hears a pattern no founder remembers making, the parish orders every bell silenced before the next fog. Yet the sound has already traveled through the pilings, and people along the estuary have begun answering it.",
  "locations": [
    {
      "id": "loc_ashcombe_foundry",
      "name": "Ashcombe Bell Foundry",
      "description": "A soot-dark workshop on a stone rise above the tide, where bronze is poured into clay molds and each founder marks a casting with a private notch. The oldest molds are kept sealed, though fresh wet clay sometimes appears on their shelves."
    },
    {
      "id": "loc_parish_of_nine",
      "name": "Parish of Nine Tides",
      "description": "A narrow cathedral whose nine storm-bells hang over a sunken nave. Gas jets warm the bell chamber, but the parish keeps the ropes locked and claims the tower has always held only eight."
    },
    {
      "id": "loc_drowned_exchange",
      "name": "The Drowned Exchange",
      "description": "A market of upper floors and boardwalks built above a flooded counting house. Oil lamps burn in glass cages, and traders pass warnings by tapping their stall posts when fog makes speech carry too far."
    },
    {
      "id": "loc_wickwater_steps",
      "name": "Wickwater Steps",
      "description": "A stairway descending into the estuary, its lower landings submerged except at the lowest ebb. The stone is scored with old tally marks that shift in number between tides."
    },
    {
      "id": "loc_saltglass_lighthouse",
      "name": "Saltglass Lantern",
      "description": "A squat harbor beacon with a gas mantle behind thick, salt-clouded glass. Its keeper charts fog by scent and claims that on certain nights the light casts a ninth shadow across the water."
    }
  ],
  "factions": [
    {
      "id": "fac_parishwardens",
      "name": "Wardens of the Nine Tides",
      "description": "The parish authority that controls the storm-bells and the records of their patterns. They have ordered the towers silenced, fearing that the unrecorded call will draw the city toward a disaster they cannot explain.",
      "location_ids": [
        "loc_parish_of_nine",
        "loc_saltglass_lighthouse"
      ]
    },
    {
      "id": "fac_founders_guild",
      "name": "The Founders' Measure",
      "description": "Bell founders, mold-makers, and apprentices bound by craft oaths. They disagree over whether the strange pattern is a forgery, a lost design, or proof that the old casting ledgers were deliberately altered.",
      "location_ids": [
        "loc_ashcombe_foundry",
        "loc_drowned_exchange"
      ]
    },
    {
      "id": "fac_lowwater_compact",
      "name": "Lowwater Compact",
      "description": "Dock families and market traders who share shelter, food, and news when the tide cuts off the lower wards. Their elders say the pattern is a map, not a warning, and want the bells rung again.",
      "location_ids": [
        "loc_drowned_exchange",
        "loc_wickwater_steps"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tidebound_fog",
      "statement": "The estuary fog follows the tide inland and retreats with it; it cannot be dispersed by ordinary wind or heat.",
      "category": "physics"
    },
    {
      "id": "rul_bronze_memory",
      "statement": "A storm-bell's exact warning depends on its bronze, mold, and casting marks; changing any one alters the pattern.",
      "category": "metaphysics"
