response.output:
{
  "world_id": "wld_leapseason_tea",
  "name": "The Fair of Folded Lanes",
  "description": "In a quiet country of hedgerows and rain-bright roads, a travelling fair arrives only during leap-season. Its lanes fold and unfold like a paper map, carrying stalls, gardens, and little kitchens from one valley to the next. A hedge-witch tea merchant follows its route, hoping to reclaim her family's place at the Ninth Stall. Here, old claims are weighed in cups of tea, bargains, friendly contests, and honest trade. The fair's gentlest wonder is also its greatest puzzle: every lane remembers its last arrangement, but no two maps agree on where the Ninth Stall belongs.",
  "locations": [
    {
      "id": "loc_rillgate_green",
      "name": "Rillgate Green",
      "description": "A village common where the fair first appears, its dew-laced tents reflected in a ring of shallow pools. Residents leave warm water and clean cups for arriving merchants."
    },
    {
      "id": "loc_ninth_stall",
      "name": "The Ninth Stall",
      "description": "A narrow, blue-painted tea booth that changes its place among the fair's lanes each morning. Its brass sign bears nine tiny cups, though one is always turned upside down."
    },
    {
      "id": "loc_brasswheel_lane",
      "name": "Brasswheel Lane",
      "description": "The fair's central passage, paved with brass-rimmed wooden tiles. Each evening, merchants trade stories and goods here while the lane gently rotates toward its next destination."
    },
    {
      "id": "loc_foldwater_bridge",
      "name": "Foldwater Bridge",
      "description": "A little bridge over a stream that seems to flow in whichever direction the fair is travelling. Its stone rail is carved with old stall numbers and half-erased family marks."
    }
  ],
  "factions": [
    {
      "id": "fac_cupkeepers_compact",
      "name": "The Cupkeepers' Compact",
      "description": "Tea sellers and kettle-menders who maintain the fair's shared customs. They believe every stall claim should be settled with a public tasting and a fair exchange.",
      "location_ids": [
        "loc_ninth_stall",
        "loc_brasswheel_lane"
      ]
    },
    {
      "id": "fac_lane_readers",
      "name": "The Lane Readers",
      "description": "Mapmakers who chart the fair by listening to the creak of its boards and the order in which its lanterns blink. Their maps are useful, but never quite complete.",
      "location_ids": [
        "loc_rillgate_green",
        "loc_brasswheel_lane",
        "loc_foldwater_bridge"
      ]
    },
    {
      "id": "fac_fair_measurers",
      "name": "The Fair Measurers",
      "description": "Keepers of stall leases, tally cords, and the fair's ceremonial contests. They favor written records, though their oldest ledger has a page that changes whenever it rains.",
      "location_ids": [
        "loc_ninth_stall",
        "loc_foldwater_bridge"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_leapseason_arrival",
      "statement": "The travelling fair can arrive only during leap-season, and its lanes must fold before the season ends.",
      "category": "metaphysics"
    },
    {
      "id": "rul_lane_memory",
      "statement": "Every fair lane remembers its previous shape, so familiar routes may be found by following repeated creaks, lantern patterns, and tile seams.",
      "category": "metaphysics"
    },
    {
      "id": "rul_claims_by_exchange",
      "statement": "Stall claims are settled through bargains, contests, and trade; a claim cannot be enforced by force.",
      "category": "social"
    },
    {
      "id": "rul_hedge_tea",
      "statement": "A hedge-witch's tea can reveal the strongest memory held by a cup, but only if the brewer shares the first sip.",
      "category": "metaphysics"
    },
    {
      "id": "rul_tally_cord",
      "statement": "A fair lease is binding only when its name is knotted into a tally cord and witnessed by both trader and keeper.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_ninth_booth_opened",
      "name": "The Ninth Booth Opens",
      "description": "The first tea seller to follow the fair's turning lanes marked a blue booth with nine cups and offered a shared pot to every new arrival.",
      "era": "First Leap-Season",
      "location_ids": [
        "loc_ninth_stall",
        "loc_brasswheel_lane"
      ]
    },
    {
      "id": "evt_cord_without_knot",
      "name": "The Cord Without a Knot",
      "description": "A family keeper entrusted the Ninth Stall's lease to the Measurers for safekeeping. The cord returned without its final knot, leaving the family's claim uncertain.",
      "era": "Several generations ago",
      "location_ids": [
        "loc_ninth_stall",
        "loc_foldwater_bridge"
      ]
    },
    {
      "id": "evt_rillgate_tasting",
      "name": "The Rillgate Tasting",
      "description": "The Cupkeepers established a public tea tasting as a way to settle disputed stall claims, asking each claimant to serve a blend that told the truth of their intent.",
      "era": "The season of three rains",
      "location_ids": [
        "loc_rillgate_green",
        "loc_brasswheel_lane"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_ninth_claim",
      "name": "Who Holds the Ninth Stall?",
      "description": "The hedge-witch's family says the missing knot was never a surrender; the Fair Measurers say the lease cannot be restored without proof. The Cupkeepers propose a tasting and an exchange, while the Lane Readers search for a route map that may reveal where the original cord was last seen. The fair is nearing the end of leap-season, so all sides must find terms before its lanes fold.",
      "faction_ids": [
        "fac_cupkeepers_compact",
        "fac_lane_readers",
        "fac_fair_measurers"
      ]
    }
  ]
}

