{
  "world_id": "wld_ice_and_coin",
  "name": "The Gilt Wake",
  "description": "The Gilt Wake is a nomad market lashed to a captured comet, where traders, pilgrims, and ship crews barter under canopies of patched sailcloth. Its fleet rides cometary currents on sails and tethers, making brief corrections with reaction plumes; every maneuver costs fuel, time, or favors. A guild factotum must arbitrate the theft of a sealed star-map before the comet's perihelion burn scatters the ships into separate trajectories. The map is more than a route chart: the comet's ancient ice preserves pressure marks in layered rings, and those rings may reveal who first claimed the market's hidden anchor tunnels. Swashbuckling bargains, disputed ownership, and daring boarding runs all unfold beneath the growing glare of the Sun.",
  "locations": [
    {
      "id": "loc_crown_market",
      "name": "Crown Market",
      "description": "A crowded bazaar bolted across the comet's broadest ridge. Its stalls fold flat for evasive maneuvers, and every vendor keeps one hand on a tether when the ground shivers."
    },
    {
      "id": "loc_anchor_catacombs",
      "name": "Anchor Catacombs",
      "description": "Narrow ice-cut passages where the oldest mooring lines disappear into the comet. Their walls hold pressure rings that can be read by touch, though rival crews disagree about what those marks prove."
    },
    {
      "id": "loc_sailyard",
      "name": "The Ragged Sailyard",
      "description": "A scaffolded dock of spars, patched canvas, and spinning rigging. Ships gather here to mend their sails and barter for skilled hands before the fleet must move."
    },
    {
      "id": "loc_blue_vault",
      "name": "Blue Vault",
      "description": "A sealed chamber in deep ice, kept cold enough to slow sublimation. The disputed star-map was last recorded here, behind a door whose lock responds to the comet's changing pressure."
    },
    {
      "id": "loc_sunward_spur",
      "name": "Sunward Spur",
      "description": "A narrow promontory facing the comet's heated side. Watch crews track the approaching perihelion burn from its signal mast, while daring pilots use the nearby debris stream as cover."
    }
  ],
  "factions": [
    {
      "id": "fac_tally_guild",
      "name": "Tally Guild",
      "description": "Market clerks, brokers, and arbiters who keep the trading ledgers and enforce agreements through access to food stores and mooring rights. Their factotums are expected to weigh evidence without owning the outcome.",
      "location_ids": [
        "loc_crown_market",
        "loc_sailyard"
      ]
    },
    {
      "id": "fac_keelwardens",
      "name": "Keelwardens",
      "description": "A cooperative of riggers and pilots responsible for the fleet's tethers, sails, and reaction-plume reserves. They believe the anchor tunnels are shared infrastructure, not private property.",
      "location_ids": [
        "loc_anchor_catacombs",
        "loc_sailyard",
        "loc_sunward_spur"
      ]
    },
    {
      "id": "fac_palimpsest",
      "name": "The Palimpsest Circle",
      "description": "Ice readers who study the comet's pressure rings as a record of past moorings. They guard their methods closely and fear that the sealed map will let outsiders rewrite the market's founding claims.",
      "location_ids": [
        "loc_anchor_catacombs",
        "loc_blue_vault"
      ]
    },
    {
      "id": "fac_sable_claim",
      "name": "Sable Claim",
      "description": "A compact of wealthy salvage captains who financed the comet's capture. They assert that the anchor tunnels and any routes recorded within them belong to their investors.",
      "location_ids": [
        "loc_crown_market",
        "loc_blue_vault",
        "loc_sunward_spur"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sail_motion",
      "statement": "Ships change course with sails, tethers, and reaction plumes; no energy weapons are used in this system.",
      "category": "technology"
    },
    {
      "id": "rul_comet_heat",
      "statement": "As the comet nears perihelion, its sunward ice sheds mass and the fleet must shorten its moorings or risk being cast adrift.",
      "category": "physics"
    },
    {
      "id": "rul_ice_record",
      "statement": "Deep ice retains pressure rings from old anchor lines, but reading those traces requires direct contact and expert interpretation.",
      "category": "other"
    },
    {
      "id": "rul_market_claims",
      "statement": "A claim to a market berth is valid only while its crew maintains a working tether and honors the guild's public ledger.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_comet_capture",
      "name": "The First Mooring",
      "description": "Salvage crews captured the comet with a chain of borrowed tethers and canvas sails. Their improvised anchor tunnels became the market's first common ground.",
      "era": "Capture Year",
      "location_ids": [
        "loc_anchor_catacombs",
        "loc_sailyard"
      ]
    },
    {
      "id": "evt_ledger_compact",
      "name": "The Tally Compact",
      "description": "After a berth dispute nearly split the early fleet, traders formed the Tally Guild and agreed that public records, rather than private threats, would settle market claims.",
      "era": "First Market Season",
      "location_ids": [
        "loc_crown_market"
      ]
    },
    {
      "id": "evt_pressure_reading",
      "name": "The Rings Beneath",
      "description": "The Palimpsest Circle discovered that pressure rings in deep ice matched old tether patterns. Their finding unsettled the Sable Claim's account of who had funded and owned the comet's anchors.",
      "era": "Three Orbits Before Present",
      "location_ids": [
        "loc_anchor_catacombs",
        "loc_blue_vault"
      ]
    },
    {
      "id": "evt_map_sealed",
      "name": "The Blue Seal",
      "description": "A star-map was sealed in the Blue Vault after its route notes appeared to align with the oldest pressure rings. The Circle and the Sable Claim each demanded custody, and the Guild recorded the vault as neutral ground.",
      "era": "Last Cold Season",
      "location_ids": [
        "loc_blue_vault",
        "loc_crown_market"
      ]
    },
    {
      "id": "evt_map_stolen",
      "name": "The Empty Vault",
      "description": "The vault was found open and the map gone. With the perihelion burn approaching, the Guild summoned an arbitration before the fleet's routes and witnesses scatter.",
      "era": "Present Approach",
      "location_ids": [
        "loc_blue_vault",
        "loc_sunward_spur",
        "loc_crown_market"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_map_custody",
      "name": "Who Owns the Route",
      "description": "The Sable Claim wants the map treated as investor property, while the Palimpsest Circle says its pressure-ring evidence belongs to the whole market. The Guild's factotum must decide what counts as proof before either side seizes the vault or destroys the records.",
      "faction_ids": [
        "fac_sable_claim",
        "fac_palimpsest",
        "fac_tally_guild"
      ]
    },
    {
      "id": "cnf_departure_clock",
      "name": "The Last Safe Mooring",
      "description": "The Keelwardens want the fleet to begin an orderly departure before heating ice weakens the anchors. The Sable Claim insists on keeping ships in place until ownership is settled, risking both the fleet and the evidence.",
      "faction_ids": [
        "fac_keelwardens",
        "fac_sable_claim",
        "fac_tally_guild"
      ]
    }
  ]
}

