response.output:
{
  "world_id": "wld_veeram_coast",
  "name": "The Rainbound Roads",
  "description": "Veeram is a pre-industrial Indian Ocean port where the monsoon is both a season and a clock. For generations, its sheltered basin has drawn merchants from distant coasts, and each year the first fair-wind departure can decide fortunes before the rains close the sea roads. The harbour scribe must reconcile three foreign envoys' rival claims to that coveted sailing slot while evidence gathers in ledgers, cargo seals, and the memories of dockworkers. Sumptuous with spice smoke, lacquered hulls, and rain-bright stone, the city grows taut as the wind shifts: a ruling made too late may cost the port its season, while a ruling made too soon could ignite a feud across the ocean.",
  "locations": [
    {
      "id": "loc_saffron_quay",
      "name": "Saffron Quay",
      "description": "The harbor's principal landing, lined with stone bollards stained gold by spice dust and monsoon runoff. Merchant crews gather here beneath striped awnings to watch the harbor flags, while porters carry cargo between the water and the counting houses."
    },
    {
      "id": "loc_rainhouse",
      "name": "The Rainhouse",
      "description": "A cool, pillared hall where the harbor scribe keeps departure ledgers, sealed petitions, and a carved wind board. Its grooves collect rainwater from the roof; local clerks read the flow as a public record of the first gusts over the outer sea."
    },
    {
      "id": "loc_copper_ladder",
      "name": "Copper Ladder Anchorage",
      "description": "A narrow inlet beyond the main quay, marked by copper rings set into black rock. Ships wait here for clearance and a favorable wind, close enough to see the harbor flags but far enough to avoid the crush of the main basin."
    },
    {
      "id": "loc_old_monsoon_gate",
      "name": "Old Monsoon Gate",
      "description": "A sea-facing arch in the older seawall, its lintel carved with waves and the names of past storm seasons. When the tide is high, water spills through its lower stones, and elders meet there to recall which captains kept faith when the weather turned."
    }
  ],
  "factions": [
    {
      "id": "fac_veeram_harbor_clerks",
      "name": "The Harbor Clerks",
      "description": "A small body of scribes, measurers, and seal-keepers charged with recording cargo, interpreting harbor custom, and assigning departure order. Their authority rests on legible records and public trust, not armed force.",
      "location_ids": [
        "loc_rainhouse",
        "loc_saffron_quay"
      ]
    },
    {
      "id": "fac_saffron_coast_envoy",
      "name": "The Saffron Coast Mission",
      "description": "Envoys representing a western spice coast claim their vessel earned precedence by delivering the port's first intact cargo tally. They bring costly gifts, exact copies of their manifests, and a crew that has waited through weeks of rain.",
      "location_ids": [
        "loc_saffron_quay",
        "loc_copper_ladder"
      ]
    },
    {
      "id": "fac_island_court_envoy",
      "name": "The Island Court Mission",
      "description": "This mission from an island court argues that a damaged harbor marker invalidated the rival tally and that its own ship first reached the anchorage under sail. Its representatives carry a carved marker fragment and insist it proves their account.",
      "location_ids": [
        "loc_copper_ladder",
        "loc_old_monsoon_gate"
      ]
    },
    {
      "id": "fac_northern_gulf_envoy",
      "name": "The Northern Gulf Mission",
      "description": "The northern envoys claim a local pilot promised them the first slot in return for carrying medicine to a storm-struck coast. Their sealed letter bears a mark recognized by some elders but absent from the harbor register.",
      "location_ids": [
        "loc_rainhouse",
        "loc_old_monsoon_gate"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_harbor_record",
      "statement": "A departure order becomes binding only when entered in the Rainhouse ledger before witnesses from the quay.",
      "category": "social"
    },
    {
      "id": "rul_seasonal_wind",
      "statement": "The monsoon winds set the safe sailing season; once the outer wind turns against a vessel's course, no harbor ruling can restore the lost passage.",
      "category": "physics"
    },
    {
      "id": "rul_wind_board",
      "statement": "The wind board records rain and gusts at the Rainhouse roof, but it cannot prove which vessel first reached the anchorage.",
      "category": "other"
    },
    {
      "id": "rul_port_tools",
      "statement": "Harbor business relies on sail, signal flags, bells, ink, and sealed documents; no device carries messages over long distances without a human bearer.",
      "category": "technology"
    },
    {
      "id": "rul_guest_right",
      "statement": "A foreign mission may petition for review, but only the harbor clerks can amend the departure ledger, and every amendment must preserve the earlier entry.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_stormwall_oath",
      "name": "The Oath at the Old Gate",
      "description": "After a disastrous storm season, harbor elders swore that no captain would be promised precedence in private. The oath made public witnessing central to departure decisions, though envoys still bring letters that test its limits.",
      "era": "Several generations before the present season",
      "location_ids": [
        "loc_old_monsoon_gate",
        "loc_rainhouse"
      ]
    },
    {
      "id": "evt_copper_rings_set",
      "name": "The Rings in the Rock",
      "description": "Port builders set copper rings into the anchorage rocks to mark a safe waiting line. A later storm broke one marker, leaving an uncertain gap that now figures in the Island Court mission's claim.",
      "era": "Within living memory",
      "location_ids": [
        "loc_copper_ladder"
      ]
    },
    {
      "id": "evt_three_petitions",
      "name": "Three Claims Before the Wind",
      "description": "As the season's first favorable gusts arrive, three missions submit incompatible claims to the first sailing slot. The harbor scribe discovers that each account relies on a different kind of evidence: cargo tallies, a broken marker, and a promise kept by word of mouth.",
      "era": "The present monsoon season",
      "location_ids": [
        "loc_saffron_quay",
        "loc_rainhouse",
        "loc_copper_ladder",
        "loc_old_monsoon_gate"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_first_wind_claim",
      "name": "The First-Wind Dispute",
      "description": "Each foreign mission says its ship has the strongest claim to the first sailing slot. Granting precedence to one risks retaliation from the others; delaying the decision risks losing the season for all three.",
      "faction_ids": [
        "fac_saffron_coast_envoy",
        "fac_island_court_envoy",
        "fac_northern_gulf_envoy",
        "fac_veeram_harbor_clerks"
      ]
    },
    {
      "id": "cnf_ledger_trust",
      "name": "The Unwritten Promise",
      "description": "The Northern Gulf mission's sealed promise has no matching ledger entry, yet several elders recognize its mark. If the clerks reject it, the mission may expose how often harbor custom has depended on private assurances; if they accept it, the written record may lose its force.",
      "faction_ids": [
        "fac_northern_gulf_envoy",
        "fac_veeram_harbor_clerks"
      ]
    }
  ]
}

