response.output:
{
  "world_id": "wld_keep_the_wick",
  "name": "The Wickward Parish",
  "description": "At the edge of a vast, wind-scoured moor lies a remote parish whose scattered wall lanterns mark the boundary between the inhabited world and something that waits in the peat. A new lamplighter inherits the rounds, the brass keys, and a ledger that records which lights endured each night. One leaf from last winter has been cut away. The parish insists that every lantern must remain lit until dawn; if all go dark together, the moor can no longer tell the living from the dead. Yet the missing night is remembered differently by everyone, and in the oldest houses, shadows sometimes point toward the wall instead of away from it. Folk horror of damp stone, inherited duties, and dread that grows with every honest question.",
  "locations": [
    {
      "id": "loc_bellwether",
      "name": "Bellwether Parish",
      "description": "A close-packed settlement of slate roofs and narrow lanes, hemmed in by black peat and low cloud. Its wall lanterns form a broken ring around the homes, each with a numbered hook and a tiny lead plate bearing the name of the household that tends it."
    },
    {
      "id": "loc_vestry",
      "name": "The Vestry of Tallies",
      "description": "A stone room behind the parish chapel where the lamp ledger is kept in a locked chest. Wax marks on the shelves show that one volume was recently removed, while a clean rectangle in the dust suggests the missing leaf was cut out here."
    },
    {
      "id": "loc_skein_bridge",
      "name": "Skein Bridge",
      "description": "A narrow causeway of laid stone crossing a peat-cut channel north of the village. Three lanterns stand along its parapet; their reflections sometimes appear in the water before the lamps are lit."
    },
    {
      "id": "loc_mothers_well",
      "name": "Mother's Well",
      "description": "A sunk spring beneath a mound of sedge, reached by a path that vanishes after heavy rain. The well's iron rim bears old wick grooves, though no one admits to lighting a lamp there. On still nights, the water gives back a fourth reflection for every three lights above it."
    }
  ],
  "factions": [
    {
      "id": "fac_lampwardens",
      "name": "The Lampwardens",
      "description": "A hereditary handful entrusted with keys, oil measures, and the nightly rounds. They teach that each lantern is a witness, not merely a light, and that a wick must never be trimmed while its flame casts no shadow.",
      "location_ids": [
        "loc_bellwether",
        "loc_skein_bridge"
      ]
    },
    {
      "id": "fac_vestry_clerks",
      "name": "The Vestry Clerks",
      "description": "The parish's keepers of births, dues, and lit nights. They maintain that the missing leaf was an accounting error, though their custodian keeps the vestry chest key on a cord beneath her clothes.",
      "location_ids": [
        "loc_vestry",
        "loc_bellwether"
      ]
    },
    {
      "id": "fac_peatkin",
      "name": "The Peatkin",
      "description": "Families who cut turf beyond the causeway and return by paths that shift with the weather. They say the lights do not keep the moor out; they teach it the parish's shape, and they have begun covering their windows rather than help tend the lamps.",
      "location_ids": [
        "loc_skein_bridge",
        "loc_mothers_well"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_one_flame",
      "statement": "At least one parish wall lantern must remain alight from dusk until dawn; on a night when every lantern goes dark, the moor can cross the boundary without being seen.",
      "category": "metaphysics"
    },
    {
      "id": "rul_named_light",
      "statement": "Every wall lantern belongs to a named household, and its light holds only while that household is acknowledged in the parish tally.",
      "category": "metaphysics"
    },
    {
      "id": "rul_wick_shadow",
      "statement": "A wick may be trimmed only while its flame casts a shadow; a shadowless flame must be carried whole to the next keeper.",
      "category": "other"
    },
    {
      "id": "rul_oil_measure",
      "statement": "Lamp oil is measured by the vestry in sealed clay cups, and no keeper may add to a measure once the nightly round begins.",
      "category": "social"
    },
    {
      "id": "rul_moor_path",
      "statement": "A path across the moor is reliable only when followed between two visible parish lights; travelers who leave that line return with peat on their shoes, even if they never touched the ground.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_first_ring",
      "name": "The First Ring of Lights",
      "description": "After a winter in which a whole hamlet vanished from the parish register, survivors set lamps along the settlement walls and assigned every light to a household. No account agrees on how many people returned.",
      "era": "Before the current parish records",
      "location_ids": [
        "loc_bellwether",
        "loc_mothers_well"
      ]
    },
    {
      "id": "evt_causeway_sinking",
      "name": "The Causeway Sinking",
      "description": "The north causeway sank waist-deep into the peat during a summer drought. When the stones were raised again, a lantern hook had appeared on the far parapet, facing the village.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_skein_bridge"
      ]
    },
    {
      "id": "evt_last_winter_leaf",
      "name": "The Cut Leaf",
      "description": "Last winter's tally contains a neat gap where one leaf was cut free. The surviving entries show every lamp lit before and after that night, but households disagree about who walked the rounds.",
      "era": "Last winter",
      "location_ids": [
        "loc_vestry",
        "loc_bellwether"
      ]
    },
    {
      "id": "evt_well_reflection",
      "name": "The Fourth Reflection",
      "description": "A Peatkin child reported seeing an extra lamp reflected in Mother's Well before any keeper had begun the evening round. The family moved nearer the village, but left their doors facing the moor.",
      "era": "The first thaw",
      "location_ids": [
        "loc_mothers_well"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_night",
      "name": "Who Cut the Night",
      "description": "The Lampwardens need the missing tally leaf to establish which lights were entrusted to which keepers, while the Vestry Clerks fear that restoring it will reveal a household deliberately erased from the register. The Peatkin claim that the erased household still answers from the moor after dusk.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_vestry_clerks",
        "fac_peatkin"
      ]
    },
    {
      "id": "cnf_broken_round",
      "name": "The Refused Round",
      "description": "Some Peatkin have stopped tending their assigned lanterns, arguing that the lights teach the moor where to find them. The Lampwardens call this a breach that endangers everyone; the Clerks see an opening to revise the household tallies before another name disappears.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_vestry_clerks",
        "fac_peatkin"
      ]
    }
  ]
}

